import{_ as t,a as o,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"第一册：英语初阶 · Lesson 105 Full of mistakes","description":"学习 动词 + 宾语 + to do，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 105 Full of mistakes","description":"学习 动词 + 宾语 + to do，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 动词 + 宾语 + to do，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 104 Too, very, enough","link":"/life/english/new-concept/book-1/unit-05/lesson-104"},"next":{"text":"第一册：英语初阶 · Lesson 106 I want you to ...","link":"/life/english/new-concept/book-1/unit-05/lesson-106"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 104 Too, very, enough","link":"/life/english/new-concept/book-1/unit-05/lesson-104"},"next":{"text":"第一册：英语初阶 · Lesson 106 I want you to ...","link":"/life/english/new-concept/book-1/unit-05/lesson-106"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-105.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-105.md"}'),l={name:"life/english/new-concept/book-1/unit-05/lesson-105.md"};function s(i,e,r,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-105-full-of-mistakes" tabindex="-1">第一册：英语初阶 · Lesson 105 Full of mistakes <a class="header-anchor" href="#第一册-英语初阶-·-lesson-105-full-of-mistakes" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 105 Full of mistakes&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-106">配套课 Lesson 106</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>提出要求并纠正文稿 本课要掌握动词 + 宾语 + to do，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>mistake</td><td>/mɪˈsteɪk/</td><td>n.</td><td>错误</td><td>make a mistake</td></tr><tr><td>correct</td><td>/kəˈrekt/</td><td>v.</td><td>纠正</td><td>correct a sentence</td></tr><tr><td>spell</td><td>/spel/</td><td>v.</td><td>拼写</td><td>spell a name</td></tr><tr><td>check</td><td>/tʃek/</td><td>v.</td><td>检查</td><td>check a report</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>ask someone to — 请某人做</li><li>full of mistakes — 充满错误</li></ul><h2 id="语法讲解-动词-宾语-to-do" tabindex="-1">语法讲解：动词 + 宾语 + to do <a class="header-anchor" href="#语法讲解-动词-宾语-to-do" aria-label="Permalink to &quot;语法讲解：动词 + 宾语 + to do&quot;">​</a></h2><p>want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Please ask Leo to check the figures.</p></blockquote><p>请让利奥检查这些数字。</p><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>tell her not to send 与 tell her to not send 相比，本课采用常见的 not to；不要用 tell she。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Please ask Leo to check the figures.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Please ask Leo to check the figures. I told her not to send the draft yet.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“提出要求并纠正文稿”写两至三句，再读给同伴听。至少使用一次动词 + 宾语 + to do，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。 Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补小词：Ask Leo ___ check the figures.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 按本课规则判断：want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“请让利奥检查这些数字。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Please ask Leo to check the figures.</p><p><strong>解析：</strong> Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：I told her not to send the draft yet.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我告诉她先不要发送草稿。</p><p><strong>解析：</strong> Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动词 + 宾语 + to do。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-104">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-106">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const p=t(l,[["render",s]]);export{k as __pageData,p as default};
